WITH account_summary AS (SELECT account_id, MIN(amount) min_amount, MAX(amount) - MIN(amount) amount_range FROM transactions WHERE HOUR(txn_time) BETWEEN 6 AND 10 GROUP BY account_id) SELECT accounts.id, accounts.account_type, account_summary.min_amount, account_summary.amount_range FROM accounts INNER JOIN account_summary ON accounts.id = account_summary.account_id WHERE account_summary.amount_range >= 80 ORDER BY account_summary.min_amount
